static void esdhc_prepare_tuning ( struct sdhci_host * host , u32 val ) { u32 reg ; mdelay ( 1 ) ; reg = readl ( host -> ioaddr + ESDHC_MIX_CTRL ) ; writel ( reg , host -> ioaddr + ESDHC_MIX_CTRL ) ; writel ( val << 8 , host -> ioaddr + ESDHC_TUNE_CTRL_STATUS ) ; dev_dbg ( mmc_dev ( host -> mmc ) , "tunning with delay 0x%x ESDHC_TUNE_CTRL_STATUS 0x%x\n" , val , readl ( host -> ioaddr + ESDHC_TUNE_CTRL_STATUS ) ) ; } 